#!/usr/bin/env node
/// <reference types="node" />
// Review comments from the deployed prototypes, brought into the repo where
// Claude works from them. `pull` writes a generated file per feature; the
// panel or `resolve` is where a comment is closed, never the file.
import { mkdirSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { featureTitle } from '../core/feature.ts';
import { type Comment, KINDS } from '../core/review/model.ts';
import type { Review } from '../core/review/service.ts';
import { jevTriager } from '../core/review/triage.ts';
import { checks } from '../server/checks.ts';
import { readEnv } from '../server/env.ts';
import { DOCS, ROOT } from '../server/paths.ts';
import { prototypes } from './lib/catalog.ts';
import { type Args, CliError, type CommandSpec } from './lib/cli.ts';
import { type CliReview, cliActor, cliReview } from './lib/review.ts';

export const spec = {
  name: 'comments',
  summary: 'Read review comments into the repo, resolve them, or sort the unsorted ones.',
  positionals: [
    {
      name: 'action',
      description:
        'summary (default): open and resolved counts per prototype. pull: docs/sprints/<feature>/comments.md, by state then kind. resolve or reopen <id>. triage: sort what Jev left unsorted, against the README states on disk.',
    },
    { name: 'id', description: 'The comment, for resolve and reopen' },
  ],
  flags: {
    all: { type: 'boolean', description: 'For pull: include resolved threads.' },
    local: {
      type: 'boolean',
      description: 'Use the local dev store even when the deployed one is configured.',
    },
  },
  output: '{ ok, store, ... } per action',
} as const satisfies CommandSpec;

const NO_STATE = 'No state';
const KIND_TITLE = { bug: 'Bugs', taste: 'Taste', copy: 'Copy' } as const;

const stateOf = (c: Comment) => c.triage?.state ?? NO_STATE;
const isRoot = (c: Comment) => c.thread === c.id;
// A body without closing punctuation gets a full stop, so the location after it reads apart from it.
const sentence = (text: string) => (/[.!?…]$/.test(text) ? text : `${text}.`);
const line = (c: Comment) =>
  `${c.author.name} (${c.author.team}): ${sentence(c.body.replace(/\s*\n\s*/g, ' '))}`;

function threadLines(root: Comment, comments: Comment[]): string[] {
  const where = root.anchor
    ? ` On \`${root.anchor.url}\`${root.anchor.target ? `, element \`${root.anchor.target}\`` : ''}.`
    : '';
  const resolved = root.status === 'resolved' ? ' Resolved.' : '';
  const replies = comments.filter((c) => c.thread === root.id && !isRoot(c));
  return [`- ${line(root)}${where}${resolved} id \`${root.id}\``, ...replies.map((r) => `  - ${line(r)}`)];
}

function stateSection(state: string, roots: Comment[], comments: Comment[]): string[] {
  const out = ['', `## ${state}`];
  for (const kind of [...KINDS, null]) {
    const group = roots.filter((c) => stateOf(c) === state && (c.triage?.kind ?? null) === kind);
    if (group.length)
      out.push(
        '',
        `### ${kind ? KIND_TITLE[kind] : 'Unsorted'}`,
        '',
        ...group.flatMap((c) => threadLines(c, comments)),
      );
  }
  return out;
}

/** One feature's comments as Markdown: by README state in table order, then kind; replies under their thread. */
export function renderComments(feature: string, comments: Comment[], stateOrder: string[]): string {
  const roots = comments.filter(isRoot);
  const states = [...new Set([...stateOrder, ...roots.map(stateOf)])].filter((s) =>
    roots.some((c) => stateOf(c) === s),
  );
  const out = [
    `# Comments: ${featureTitle(feature)}`,
    '',
    'Generated by `pnpm comments pull`; a second pull replaces it. Resolve a comment in the review panel or with `pnpm comments resolve <id>`, never here.',
    ...states.flatMap((state) => stateSection(state, roots, comments)),
  ];
  return `${out.join('\n')}\n`;
}

type Context = { review: Review; store: CliReview['store']; all: Comment[]; roots: Comment[] };

export function summary({ store, roots }: Pick<Context, 'store' | 'roots'>) {
  const by: Record<string, { open: number; resolved: number }> = {};
  for (const c of roots) {
    const key = c.anchor?.prototype ?? 'unknown';
    by[key] ??= { open: 0, resolved: 0 };
    by[key][c.status]++;
  }
  return { store, prototypes: by };
}

function pull({ store, all, roots }: Context, includeResolved: boolean) {
  const keep = new Map(roots.filter((c) => includeResolved || c.status === 'open').map((c) => [c.id, c]));
  const byFeature = new Map<string, Comment[]>();
  for (const c of all) {
    const root = keep.get(c.thread);
    if (!root) continue;
    const feature = root.anchor?.feature || root.anchor?.prototype || 'unsorted';
    byFeature.set(feature, [...(byFeature.get(feature) ?? []), c]);
  }
  const disk = prototypes();
  const written = [...byFeature].map(([feature, comments]) => {
    const order = disk
      .filter((p) => p.feature === feature)
      .flatMap((p) => (p.states ?? []).map((s) => s.name));
    const dir = join(DOCS, 'sprints', feature);
    mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, 'comments.md'), renderComments(feature, comments, order));
    return relative(ROOT, join(dir, 'comments.md'));
  });
  return { store, threads: keep.size, written };
}

async function setStatus({ review, store }: Context, id: string | undefined, resolved: boolean) {
  const action = resolved ? 'resolve' : 'reopen';
  if (!id)
    throw new CliError(`Name the comment: pnpm comments ${action} <id>.`, {
      fix: 'pnpm comments pull lists ids.',
    });
  const found = await review.locate(id);
  if (!found) throw new CliError('No comment has that id.', { id });
  const comment = await review.resolve(cliActor(), { prototype: found.prototype, id, resolved });
  return { store, comment: { id: comment.id, status: comment.status } };
}

async function triage({ review, store, roots }: Context) {
  const triager = jevTriager(readEnv(ROOT).TYPESAFE_API_KEY ?? '', checks);
  if (!triager)
    throw new CliError('TypeSafe is off.', {
      fix: 'pnpm bootstrap --typesafe-key <key>, or sort them in the panel.',
    });
  const statesOf = new Map(prototypes().map((p) => [p.slug, (p.states ?? []).map((s) => s.name)]));
  const sorted: string[] = [];
  for (const c of roots) {
    if (c.triage || !c.anchor) continue;
    const states = statesOf.get(c.anchor.prototype) ?? [];
    const t = await triager({ body: c.body, prototype: c.anchor.prototype, url: c.anchor.url, states });
    if (!t) continue;
    await review.retriage(cliActor(), { prototype: c.anchor.prototype, id: c.id, triage: t, states });
    sorted.push(c.id);
  }
  return { store, sorted };
}

export async function main({ positionals: [action = 'summary', id], flags }: Args<typeof spec>) {
  const { review, store } = cliReview(flags.local);
  const all = await review.allComments();
  const ctx: Context = { review, store, all, roots: all.filter(isRoot) };
  switch (action) {
    case 'summary':
      return summary(ctx);
    case 'pull':
      return pull(ctx, flags.all);
    case 'resolve':
    case 'reopen':
      return setStatus(ctx, id, action === 'resolve');
    case 'triage':
      return triage(ctx);
    default:
      throw new CliError(`Unknown action ${action}.`, { fix: 'summary, pull, resolve, reopen or triage' });
  }
}
